from taf.ul.trs_e2e_fw.lib.ems.netact.netact_base import NetactBase
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable

logger = BackgroundLogger.Instance()

class WorkSetManager(NetactBase):

    def __init__(self):
        super(WorkSetManager, self).__init__()

    def create_working_set(self, **kwargs):
        """
        Create a working set with defined managed objects using import command.

        @param kwargs:
            set_name: string, Name of the working set to be created
            dist_names: str|list(str), Distinguished name(s) of managed object(s) to be attached to the working set
            timeout: int, Timeout for executing operation
            alias: string, Netact instance name. Default value is 'default'.

        @return: Command's output
        """
        set_name = kwargs.pop('set_name', 'iv_fw_plan')
        dist_names = kwargs['dist_names']
        alias = kwargs.pop('alias', 'default')
        timeout = kwargs.pop('timeout', 120)
        config_device = kwargs.get('config_device')
        tool_config = get_config_variable(['ems', config_device])
        self.netact_factory.netact.add_node(service_name='syswas', hostname=tool_config['was_host'],
                                                username=tool_config['was_ssh_user'],
                                                password=tool_config['was_ssh_pass'],
                                                alias=alias)
        return self.netact_factory.netact.create_working_set(ws_name=set_name, dist_names=dist_names, timeout=timeout, alias=alias)

    def run_diagnostic_check(self, **kwargs):
        """
        This operation is used for executing diagnostic checks for SRAN BTSs

        @param kwargs:
            working_sets: string, Specifies the scope of the operation as defined in the working set. At least one of
            the arguments dist_names or working_sets must be defined
            dist_names: str|list(str), If PLMN is not defined, PLMN-PLMN prefix is automatically added e.g., PLMN-PLMN/MRBTS-1
            allow_service_impact: bool,  Indicates if also diagnostic checks causing BTS reset are executed
            export_feedback: bool, If True, KW returns a detailed output from executed operation
            ignore_errors: bool, If True, KW shows warnings instead of raising errors when operation fails
            timeout: int, Timeout for executing operation
            alias: string, Netact instance name. Default value is 'default'.

        @return: Operation's output
        """
        working_sets = kwargs.pop('working_sets', None)
        dist_names = kwargs.pop('dist_names', None)
        allow_service_impact = kwargs.pop('allow_service_impact', False)
        verbose = kwargs.pop('export_feedback', False)
        ignore_errors = kwargs.pop('ignore_errors', False)
        timeout = kwargs.pop('timeout', 7200)
        alias = kwargs.pop('alias', 'default')
        return self.netact_factory.netact.run_diagnostic_check(dist_names=dist_names, working_sets=working_sets,
                                                               allow_service_impact=allow_service_impact, verbose=verbose,
                                                               ignore_errors=ignore_errors, timeout=timeout, alias=alias)

    def delete_working_sets(self, **kwargs):
        """
        Delete the defined working sets.

        @param kwargs:
            set_name: string, Name of the working set to be created
            ignore_errors: bool, If True, shows warnings instead of raising errors
            when command fails.
            timeout: int, Timeout for executing operation
            alias: string, Netact instance name. Default value is 'default'.

        @return: Command's output
        """
        set_name = kwargs.pop('set_name', 'iv_fw_plan')
        ignore_errors = kwargs.pop('dist_names', False)
        alias = kwargs.pop('alias', 'default')
        timeout = kwargs.pop('timeout', 120)
        return self.netact_factory.netact.delete_working_sets(ws_name=set_name, ignore_errors=ignore_errors,
                                                              timeout=timeout, alias=alias)